import axios from 'axios';
import http from 'http';
import url from 'url';
import { writeGlobalCliConfig } from './utils/config.util';
import { MKDB_BASE_URL } from './utils/env.util';
import logger, { withColor } from './utils/logger.util';

const LOCAL_SERVER_PORT = 42069;

const corsHeaders = {
  'Access-Control-Allow-Origin': '*' /* @dev First, read about security */,
  'Access-Control-Allow-Methods': 'OPTIONS, POST, GET',
  'Access-Control-Max-Age': 2592000, // 30 days
  'Access-Control-Allow-Headers':
    'Content-Type, Authorization, baggage, sentry-trace',
};

// Start the server function
export function startUserLoginServer(
  onStarted: () => void,
  onUserLoggedIn?: (user: any) => void,
) {
  const server = http.createServer(async (req, res) => {
    if (req.url === '/status') {
      res.writeHead(200, { 'Content-Type': 'text/plain', ...corsHeaders });
      res.end('ok');
      return;
    }

    logger.dev.log('req.url', req.url);
    const token = url.parse(`localhost:${LOCAL_SERVER_PORT}${req.url}`, true)
      .query?.token;
    logger.dev.log('token', token);

    let user;
    if (token) {
      const res = await axios
        .get(`${MKDB_BASE_URL}/api/users`, {
          headers: {
            Authorization: `${token}`,
          },
        })
        .catch((err) => {
          logger.log('err', err.response.data);
          return undefined;
        });
      user = res?.data;

      logger.dev.logJson(res?.data);
    }

    res.writeHead(200, { 'Content-Type': 'text/plain' });
    res.end(
      "nice, you're logged in muchacho.  you can go back to your CLI now friend.",
    );
    // Optionally, you can close the server when a response is sent
    server.close();
    onUserLoggedIn?.(user);

    if (user) {
      logger.log(`\nLogged in as: ${withColor(user.name)}`);

      writeGlobalCliConfig({ user: { ...user, apiToken: token } });
    }
  });

  server.listen(LOCAL_SERVER_PORT, () => {
    onStarted();
  });
}
